import{_ as t,o,c as a,a1 as d}from"./chunks/framework.DIevSSiF.js";const p=JSON.parse('{"title":"Local event vocabulary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/telemetry.md","filePath":"reference/telemetry.md"}'),r={name:"reference/telemetry.md"};function n(i,e,s,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="local-event-vocabulary" tabindex="-1">Local event vocabulary <a class="header-anchor" href="#local-event-vocabulary" aria-label="Permalink to &quot;Local event vocabulary&quot;">​</a></h1><p>Shadow has no network transport for these events. With <code>SHADOW_TELEMETRY=local</code>, a successful <code>shadow throw</code> appends one bounded JSON line to <code>.shadow/evidence/shadow-events.jsonl</code> in that exact project. Every other value, including an unset variable, leaves the writer off. The event file is mode <code>0600</code>; its parent directories and destination are opened without following symlinks.</p><p>Unknown input fields are omitted when the record is constructed, so there is no later scrub pass that temporarily holds a wider payload. Values remain untrusted at construction. The local writer accepts only a lowercase project slug, a 64-hex logical entity id, a four-character row id, fixed verb and outcome vocabularies, a bounded integer duration, and a UTC timestamp. It records no seat, plan text, proof command or output, environment value, repository path, provider, or account.</p><p>The local file is optional observation, never authority. Failure to append it does not undo or contradict a durable claim; <code>shadow throw</code> reports that fixed condition without exposing the failed path. Nothing reads the file to choose, claim, accept, or resume work.</p><p>The closed field vocabulary is:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>schema</code></td><td>Fixed local event schema identifier.</td></tr><tr><td><code>recorded_at</code></td><td>UTC event time.</td></tr><tr><td><code>project</code></td><td>Lowercase project slug.</td></tr><tr><td><code>entity</code></td><td>Logical entity identifier.</td></tr><tr><td><code>row</code></td><td>Checkpoint row identifier.</td></tr><tr><td><code>verb</code></td><td>Shadow lifecycle verb.</td></tr><tr><td><code>duration_ms</code></td><td>Bounded elapsed milliseconds.</td></tr><tr><td><code>outcome</code></td><td>Lifecycle outcome.</td></tr></tbody></table><h2 id="local-sink-—-the-owner-s-endpoint-decision-2026-08-11" tabindex="-1">Local sink — the owner&#39;s endpoint decision (2026-08-11) <a class="header-anchor" href="#local-sink-—-the-owner-s-endpoint-decision-2026-08-11" aria-label="Permalink to &quot;Local sink — the owner&#39;s endpoint decision (2026-08-11)&quot;">​</a></h2><p>The owner decided the endpoint: a <strong>Langfuse instance on the owner&#39;s own machine</strong> (<code>http://localhost:3000</code>), for debugging and observability while long test jobs run against Shadow. The decision&#39;s scope, in plain terms:</p><ul><li><strong>The product still sends nothing, ever.</strong> The ~obsv verdict — Langfuse KILLED as a product dependency, because Shadow makes zero network calls — stands untouched. No product verb gains network code.</li><li><strong>The sink is owner tooling</strong>: <code>scripts/dev/shadow-observed-gauntlet.py</code> runs long test jobs and ships their traces (and, optionally, the already allowlisted local event file) to the local Langfuse over OTLP. It refuses to run unless <code>SHADOW_LANGFUSE_HOST</code>, <code>SHADOW_LANGFUSE_PUBLIC_KEY</code>, and <code>SHADOW_LANGFUSE_SECRET_KEY</code> are all set. A machine without those set — every user machine — behaves exactly as it does today.</li><li><strong>The approved field subset</strong> for forwarded events is exactly the closed vocabulary above — the forwarder adds job name, exit code, pass/fail, duration, and a home-path-redacted output tail for its own test jobs, and nothing else.</li><li>The compose file and provisioned keys live outside the repository, on the owner&#39;s machine only.</li></ul>',9)])])}const v=t(r,[["render",n]]);export{p as __pageData,v as default};
